def caesar_cipher(text, shift):
    result = []
    for ch in text:
        if ch.islower():
            result.append(chr((ord(ch) - ord('a') + shift) % 26 + ord('a')))
        elif ch.isupper():
            result.append(chr((ord(ch) - ord('A') + shift) % 26 + ord('A')))
        else:
            result.append(ch)
    return ''.join(result)
```

